import Synchronization

/// Read-only view of a pasteboard, so the watcher can be tested without `NSPasteboard`.
public protocol PasteboardReading: Sendable {
    var changeCount: Int { get }
    func string() -> String?
    func types() -> [String]
}

/// Polls a pasteboard and reports newly copied plain text.
///
/// The `changeCount` seen at init is the baseline, so whatever was on the clipboard before
/// Remora started is never captured. Copies flagged by the nspasteboard.org conventions as
/// concealed (password managers), transient or auto-generated are consumed without firing.
public final class ClipboardWatcher: Sendable {
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    private let pasteboard: any PasteboardReading
    private let onText: @Sendable (String) -> Void
    private let lastChangeCount: Mutex<Int>

    public init(pasteboard: any PasteboardReading, onText: @escaping @Sendable (String) -> Void) {
        self.pasteboard = pasteboard
        self.onText = onText
        self.lastChangeCount = Mutex(pasteboard.changeCount)
    }

    /// Used while capture is paused: moves the baseline to the current `changeCount` without
    /// reading the pasteboard's types or content, so a copy made during the pause is never
    /// read, now or after resuming.
    public func consumeWithoutReading() {
        let current = pasteboard.changeCount
        lastChangeCount.withLock { $0 = current }
    }

    /// Checks the pasteboard once. Returns the newly copied text (also passed to `onText`),
    /// or `nil` when nothing new and acceptable was copied.
    @discardableResult
    public func poll() -> String? {
        let current = pasteboard.changeCount
        let changed = lastChangeCount.withLock { last in
            defer { last = current }
            return last != current
        }
        guard changed else { return nil }
        if pasteboard.types().contains(where: Self.ignoredTypes.contains) { return nil }
        guard let text = pasteboard.string(),
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        // A new item (possibly concealed) landed between `types()` and `string()`: the text
        // may belong to it, so drop it. The new item is evaluated on the next poll.
        guard pasteboard.changeCount == current else { return nil }
        onText(text)
        return text
    }
}
